import sqlite3

# Connect in read-only mode
con = sqlite3.connect('file:/home/user/guidebook/data/guidebook.db?mode=ro', uri=True)

# 1. PRAGMA user_version (schema version)
schema_version = con.execute('PRAGMA user_version').fetchone()[0]
print(f"SCHEMA VERSION: {schema_version}\n")

# 2. Get all tables and row counts
tables = con.execute(
    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
).fetchall()

table_names = [t[0] for t in tables]
row_counts = {}
empty_tables = []

print("ROW COUNTS BY TABLE:")
for table in table_names:
    count = con.execute(f'SELECT COUNT(*) FROM "{table}"').fetchone()[0]
    row_counts[table] = count
    print(f"  {table}: {count}")
    if count == 0:
        empty_tables.append(table)

if empty_tables:
    print(f"\nEMPTY TABLES (0 rows): {empty_tables}")
else:
    print("\nEMPTY TABLES: [NULL: examined all tables, none empty]")

# 3. Find UNWRITABLE tables (NOT NULL FK into empty tables)
print("\nUNWRITABLE TABLES (NOT NULL FK → empty table):")
unwritable_found = False

empty_set = set(empty_tables)

for table in table_names:
    # Get foreign keys for this table
    fks = con.execute(f'PRAGMA foreign_key_list("{table}")').fetchall()

    # Check each FK to see if it points to an empty table
    for fk in fks:
        # fk: (id, seq, table, from, to, on_delete, on_update, match, implicit)
        from_col = fk[3]
        target_table = fk[2]

        if target_table in empty_set:
            # Check if the from_col is NOT NULL
            col_info = con.execute(f'PRAGMA table_info("{table}")').fetchall()
            for col in col_info:
                # col: (cid, name, type, notnull, dflt_value, pk)
                if col[1] == from_col and col[3]:  # col[3] is notnull flag
                    print(f"  {table}.{from_col} NOT NULL → {target_table} (empty)")
                    unwritable_found = True

if not unwritable_found:
    print("  [NULL: examined FK constraints, none point NOT NULL to empty tables]")

# 4. Check for session/batch id columns to show session attribution
print("\nSESSION ATTRIBUTION (if session/batch columns exist):")
session_cols = {}
for table in table_names:
    col_info = con.execute(f'PRAGMA table_info("{table}")').fetchall()
    for col in col_info:
        col_name = col[1]
        if 'session' in col_name.lower() or 'batch' in col_name.lower():
            if table not in session_cols:
                session_cols[table] = []
            session_cols[table].append(col_name)

if session_cols:
    for table, cols in sorted(session_cols.items()):
        print(f"  {table}: {cols}")
        # Sample the most recent values if rows exist
        if row_counts[table] > 0:
            for col in cols:
                try:
                    recent = con.execute(
                        f'SELECT DISTINCT "{col}" FROM "{table}" ORDER BY rowid DESC LIMIT 3'
                    ).fetchall()
                    if recent:
                        vals = [r[0] for r in recent]
                        print(f"    Recent {col}: {vals}")
                except:
                    pass
else:
    print("  [NULL: no session/batch columns found in schema]")

con.close()
